import re
from datetime import datetime

_DIGITS = "0123456789"
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _text(value):
    return "" if value is None else str(value)


def _normalize_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = _text(raw)
    m = re.search(r"<([^<>]*)>", s)  # display name form: use only the part in <...>
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "").split("+", 1)[0]
        domain = "gmail.com"
    if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return local + "@" + domain


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    s = _text(raw).lower()
    cuts = [i for i in (s.find("x"), s.find("ext"), s.find("#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    """Return a 5-digit ZIP, or "" if it cannot be made into one."""
    z = _text(raw).strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", z)  # ZIP+4: keep the part before the hyphen
    if m:
        z = m.group(1)
    if len(z) == 4 and all(c in _DIGITS for c in z):  # Excel ate the leading zero
        z = "0" + z
    if len(z) == 5 and all(c in _DIGITS for c in z):
        return z
    return ""


def _normalize_name(raw):
    s = _text(raw).strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = _text(raw).strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None


def _normalize_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", _text(raw)) if t.strip()}


def _pick(group, field):
    """Pick the field value from the best row in the group.

    Preference: source "manual", then most recent `updated`, then earliest input row.
    `group` is in input order, and each sort below is stable, so ties keep input order.
    """
    cands = [r for r in group if r[field]]
    if not cands:
        return ""
    cands.sort(key=lambda r: r["updated"] if r["updated"] is not None else datetime.min,
               reverse=True)
    cands.sort(key=lambda r: r["source"] != "manual")
    return cands[0][field]


def _summarize(group):
    dates = [r["updated"] for r in group if r["updated"] is not None]
    latest = max(dates).strftime("%Y-%m-%d") if dates else ""
    tags = set()
    for r in group:
        tags |= r["tags"]
    return {
        "first_name": _pick(group, "first_name"),
        "last_name": _pick(group, "last_name"),
        "zip": _pick(group, "zip"),
        "email": _pick(group, "email"),
        "phone": _pick(group, "phone"),
        "source": _pick(group, "source"),
        "tags": ";".join(sorted(tags)),
        "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
        "updated": latest,
    }


def dedupe_contacts(rows):
    # Normalize each row, dropping rows with neither a valid email nor a valid phone.
    recs = []
    for row in rows:
        email = _normalize_email(row.get("email"))
        phone = _normalize_phone(row.get("phone"))
        if not email and not phone:
            continue
        recs.append({
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email,
            "phone": phone,
            "source": _text(row.get("source")).strip().lower(),
            "tags": _normalize_tags(row.get("tags")),
            "opted_out": _text(row.get("opted_out")).strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row.get("updated")),
        })

    # Union-find over rows. Rows sharing a valid email, or a valid phone plus
    # the same non-empty last name, are unioned. This makes matching transitive.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email = {}
    by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in by_email:
                union(i, by_email[r["email"]])
            else:
                by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in by_phone_last:
                union(i, by_phone_last[key])
            else:
                by_phone_last[key] = i

    # Group rows. Dict insertion order follows each group's earliest row,
    # so the output is ordered by first appearance in the input.
    groups = {}
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    return [_summarize(g) for g in groups.values()]
